CREATE TYPE public.app_role AS ENUM ('host');
CREATE TABLE public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role public.app_role not null, unique(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.is_host() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='host') $$;
CREATE TABLE public.rsvps (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now(), full_name text not null check(length(full_name) between 2 and 150), phone text not null check(length(phone) between 7 and 30), email text not null check(length(email) between 5 and 254), attending text not null check(attending in ('Yes','No','Maybe')), guests integer not null default 1 check(guests between 1 and 50), dietary text not null default '' check(length(dietary)<=2000), song text not null default '' check(length(song)<=500), message text not null default '' check(length(message)<=3000));
GRANT INSERT ON public.rsvps TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rsvps TO authenticated;
GRANT ALL ON public.rsvps TO service_role;
ALTER TABLE public.rsvps ENABLE ROW LEVEL SECURITY;
CREATE POLICY guest_submit ON public.rsvps FOR INSERT TO anon,authenticated WITH CHECK(true);
CREATE POLICY host_read ON public.rsvps FOR SELECT TO authenticated USING(public.is_host());
CREATE POLICY host_update ON public.rsvps FOR UPDATE TO authenticated USING(public.is_host()) WITH CHECK(public.is_host());
CREATE POLICY host_delete ON public.rsvps FOR DELETE TO authenticated USING(public.is_host());
ALTER PUBLICATION supabase_realtime ADD TABLE public.rsvps;
CREATE TABLE public.invitation_photos (slot text primary key check(slot in ('hero','moment1','moment2','moment3')), url text not null);
GRANT SELECT ON public.invitation_photos TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.invitation_photos TO authenticated;
GRANT ALL ON public.invitation_photos TO service_role;
ALTER TABLE public.invitation_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_photos ON public.invitation_photos FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY host_photos ON public.invitation_photos FOR ALL TO authenticated USING(public.is_host()) WITH CHECK(public.is_host());